import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/ConvS2S.html","title":"ConvS2S","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.62,"words":187},"filePathRelative":"ConvS2S.md"}`),a={name:`ConvS2S.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="convs2s" tabindex="-1"><a class="header-anchor" href="#convs2s"><span>ConvS2S</span></a></h1><p><a href="./機械翻訳.html">機械翻訳</a>にRNNでは無くCNNを使う事を提唱した<a href="./論文.html">論文</a>。別名: <a href="./ConvolutionalSequenceToSequenceLearning.html">ConvolutionalSequenceToSequenceLearning</a></p><ul><li><a href="https://arxiv.org/abs/1705.03122" target="_blank" rel="noopener noreferrer">arxiv:1705.03122 Convolutional Sequence to Sequence Learning</a></li><li><a href="https://github.com/facebookresearch/fairseq/blob/3d262bb25690e4eb2e7d3c1309b1e9c406ca4b99/fairseq/models/fconv.py#L33" target="_blank" rel="noopener noreferrer">fairseq/fairseq/models/fconv.py at 3d262bb25690e4eb2e7d3c1309b1e9c406ca4b99 · facebookresearch/fairseq</a> 実装はこれか。</li></ul><h2 id="transformerを踏まえた特徴" tabindex="-1"><a class="header-anchor" href="#transformerを踏まえた特徴"><span>Transformerを踏まえた特徴</span></a></h2><p><a href="./Transformer.html">Transformer</a>へとつながる数々のアイデアがある。</p><ul><li>Positional embedding</li><li>Multi step attention</li></ul><p>初期化は結構大変そう。</p><h2 id="ノーテーション" tabindex="-1"><a class="header-anchor" href="#ノーテーション"><span>ノーテーション</span></a></h2><p><img src="/RandomThoughts/assets/0000-DohgCnkq.png" alt="imgs/ConvS2S/0000.png"></p><p>入力はmトークン、一つあたりV次元だが、embedによりこれがf次元となる（ただしfやVは以後あまり出てこない）。</p><h2 id="cnnブロック" tabindex="-1"><a class="header-anchor" href="#cnnブロック"><span>CNNブロック</span></a></h2><p><img src="/RandomThoughts/assets/0002-CjyHPXRP.png" alt="imgs/ConvS2S/0002.png"></p><p><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>i</mi><mi>k</mi></msub></mrow><annotation encoding="application/x-tex">i_k</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8095em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">i</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> というのはk個の入力、という意味。一つあたりd次元。ちなみに5.1での実験のkは3とか。</p><p>入力は実際はm個あり、これをkずつconvolutionしていく。結果もm個となる。1個あたりの次元も最終的にはdになるので、入力と同じ個数、次元となる。</p><p>この2倍の次元を出力して、半分にsigmoidを掛けてpoint wise multiplyするのはGLU（gated linear unit）というものらしい。</p><h2 id="encoder-decoderの概略" tabindex="-1"><a class="header-anchor" href="#encoder-decoderの概略"><span>Encoder-Decoderの概略</span></a></h2><p><img src="/RandomThoughts/assets/0003-DBCJRMMX.png" alt="imgs/ConvS2S/0003.png"></p><p>cがAttention。Decoderの各レイヤにある。</p><h3 id="アテンション" tabindex="-1"><a class="header-anchor" href="#アテンション"><span>アテンション</span></a></h3><p><img src="/RandomThoughts/assets/0004-DR5gwP3r.png" alt="imgs/ConvS2S/0004.png"></p><p>dはhと<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>g</mi><mi>i</mi></msub></mrow><annotation encoding="application/x-tex">g_i</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>の線形和（decoder state summaryと呼んでいる）。このdecoderの状態要約とzの関係で求めるアテンションとなる。 オリジナルの<a href="./アテンション.html">アテンション</a>と比べると、単純にhとのalignでは無くgiも含めた現時点のデコーダーのコンテキスト的なものを使うのと、元入力である<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>e</mi><mi>j</mi></msub></mrow><annotation encoding="application/x-tex">e_j</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7167em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal">e</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>が入っていたりするのが違う。</p><h2 id="positional-embedding" tabindex="-1"><a class="header-anchor" href="#positional-embedding"><span>Positional Embedding</span></a></h2><p><a href="./PositionEmbeddings.html">PositionEmbeddings</a>へ。</p>`,23)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};